import{_ as i,l as s,o as e,c as n,v as r,p as l,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"哈希聚合","description":"","frontmatter":{"title":"哈希聚合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hash-aggregation.md","filePath":"cs/hash-aggregation.md","lastUpdated":1789023840000}'),p={name:"cs/hash-aggregation.md"};function E(B,a,_,g,A,m){const t=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="哈希聚合" tabindex="-1">哈希聚合 <a class="header-anchor" href="#哈希聚合" aria-label="Permalink to &quot;哈希聚合&quot;">​</a></h1><div class="epigraph"><p>按分组键散到桶，组状态留在表项里；内存够则一次扫描，不够则分区再递归，形状对齐哈希连接。</p><footer>—— 据 Graefe 聚合方法；Ramakrishnan and Gehrke；GROUP BY 语义课的物理实现</footer></div><p><a href="/cs/external-sort">上一课</a>用排序做阻塞有序输出。本课不造 run。缺口是 <a href="/cs/sql-aggregation">GROUP BY</a> 的常用物理：哈希聚合。等值分组不必全序；排序聚合在要顺串或组数极大、内存极小且键已有序时仍有地位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描一行，用分组键探测哈希表：命中则更新 <code>SUM</code>/<code>COUNT</code> 状态，未命中则插入新组。结束时扫描哈希表吐结果（无序，除非再排）。缺口是内存：组数 ≈ NDV(分组键)。估小了表膨胀，必须溢出到分区（与 Grace 哈希连接同一思想）：按键高位划分，各分区分别聚合再并。</p><p>倾斜：单组极大（所有行同一键）哈希帮不上分区——该组状态仍可能很小（一个合计），行仍要扫完。倾斜伤的是连接探测，聚合里伤的是「热组」更新争用（并行时）。</p><p><span class="marginnote">两阶段聚合：先线程局部聚合，再全局合并，减少锁。流式聚合与窗口不同：窗口不收缩。本课收缩成每组一行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内存哈希聚合；溢出则写分区文件，每分区再哈希或排序聚合。<code>DISTINCT</code> 聚合：组内再套集合或哈希集。<code>FILTER</code> 在更新状态前判。空组规则在语义课已钉，执行器对无 <code>GROUP BY</code> 的裸聚合要在空输入时仍吐一行。</p><p>与向量化：按批探测，用选择向量。编译：生成针对具体聚合函数的更新代码。</p>',10)),(e(),l(h,null,{default:o(()=>[c(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E8%A1%8C%22%5D%20--%3E%20H%5B%22%E6%8E%A2%E6%B5%8B%E5%88%86%E7%BB%84%E5%93%88%E5%B8%8C%E8%A1%A8%22%5D%0A%20%20H%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%E7%BB%84%E7%8A%B6%E6%80%81%22%5D%0A%20%20MEM%5B%22%E5%86%85%E5%AD%98%E4%B8%8D%E8%B6%B3%22%5D%20--%3E%20PART%5B%22%E6%8C%89%E9%94%AE%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%20--%3E%20H%0A%20%20H%20--%3E%20OUT%5B%22%E6%89%AB%E6%8F%8F%E8%A1%A8%E5%90%90%E7%BB%84%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>基数估计决定选哈希还是排序：估 NDV 过低会选哈希然后溢盘，可能比一开始排序更差——估计误差课的实例。计划回归可表现为聚合算子种类切换。</p><p>并行：local agg + exchange 按组键重分区 + global agg。exchange 下一课之后；本课单机内存模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Grace hash join 的探测侧细节——下一课专讲连接。聚合没有 probe 输入，只有一组输入。窗口函数不是哈希聚合。</p><p>后课默认：等值 <code>GROUP BY</code> 默认哈希聚合，溢盘分区；要有序输出再加排序。Grace 连接把「分区再处理」用在两输入上。</p><p>哈希表的组状态大小计入内存预算，不只是键。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>哈希聚合一次扫描更新组状态；组 NDV 决定能否驻留。</li><li>溢出分区与哈希连接同源；空输入裸聚合仍要吐行。</li><li>Grace hash join 下一课：两输入的分区哈希连接。</li><li>出处：Graefe；Ramakrishnan and Gehrke；聚合语义对照。</li></ul>',9))])}const T=i(p,[["render",E]]);export{u as __pageData,T as default};
